"use client"

import * as React from "react"
import { Check, Pipette } from "lucide-react"

import { cn } from "@/lib/utils"
import { readColor, SAME_COLOR, type ColorIssue, type ColorReading } from "./color"

export { cleanColor, colorDistance, NEAR_COLOR, nearestToken, readColor, SAME_COLOR, toHex, toOklab, type ColorIssue, type ColorReading, type RGBA } from "./color"

/** Every sentence the field can show. `i` is the issue, `r` the whole reading. */
export const BRAND_COLOR_MESSAGES = {
  unreadable: () => "Not a colour this field can read. Use hex (#1e40af) or rgb(30 64 175).",
  stray: (i: ColorIssue) => `Extra characters around the colour. It reads as ${i.fix}.`,
  lookalike: () => "That's a letter O or l, not a zero or one. Hex only uses 0–9 and A–F.",
  digits: (i: ColorIssue) =>
    `${i.detail} digits isn't a hex colour (it needs 3, 4, 6 or 8).${i.token ? ` One digit away from ${i.token}.` : ""}`,
  argb: (i: ColorIssue) =>
    `Alpha comes first here, like Android's #AARRGGBB. CSS reads alpha last and would show ${i.detail}.`,
  "short-alpha": (i: ColorIssue) => `A 4th digit is alpha: this renders as ${i.detail}, partly see-through.`,
  transparent: () => "Alpha is 00, so this colour is fully transparent.",
  "alpha-range": (i: ColorIssue) => `Alpha ${i.detail} is out of range. CSS wants 0–1 or a percentage.`,
  "out-of-range": () => "A channel is outside 0–255 and will be clamped.",
  near: (i: ColorIssue, r: ColorReading) =>
    (r.nearest?.distance ?? 1) < SAME_COLOR
      ? `Looks identical to ${i.token}, but isn't the same value.`
      : `Close to ${i.token}, but not the brand value.`,
  exact: (r: ColorReading) => `Matches ${r.nearest?.token}.`,
  nearest: (r: ColorReading) => `Not a brand colour. Nearest is ${r.nearest?.token} (${r.nearest?.hex}).`,
}

export interface BrandColorInputProps extends Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "onChange"> {
  /** Visible label. */
  label?: string
  /** Controlled text. */
  value?: string
  /** Initial text when uncontrolled. */
  defaultValue?: string
  /** Called with the text on every change, including one-tap fixes. */
  onValueChange?: (value: string) => void
  /** Called with the canonical hex the text renders as, or null when it can't be read. */
  onColorChange?: (hex: string | null) => void
  /** Brand tokens by name, e.g. { "blue-700": "#1e40af" }. */
  palette?: Record<string, string>
  /** Override any message. */
  messages?: Partial<typeof BRAND_COLOR_MESSAGES>
  /** Label of the one-tap fix that snaps to a token ("Use blue-700"). */
  snapLabel?: string
  /** Label of the other one-tap fixes. */
  fixLabel?: string
}

const NO_PALETTE: Record<string, string> = {}
const fieldClass =
  "h-9 w-full min-w-0 rounded-md border bg-transparent pr-3 pl-10 font-mono text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 md:text-sm dark:bg-input/30 aria-invalid:border-destructive data-warning:border-amber-500 dark:data-warning:border-amber-400"
const fixClass =
  "inline-flex h-6 items-center gap-1.5 rounded-md border border-amber-500/40 px-2 font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
// Checkerboard under the swatch so alpha is visible instead of silently blending into the page.
const checker = "bg-[conic-gradient(#ccc_25%,#fff_0_50%,#ccc_0_75%,#fff_0)] bg-[length:8px_8px]"

function Swatch({ color, className }: { color: string | null; className?: string }) {
  return (
    <span aria-hidden className={cn("relative inline-block overflow-hidden rounded-sm border", checker, className)}>
      <span className="absolute inset-0" style={{ background: color ?? "transparent" }} />
    </span>
  )
}

/** The fixed hex with the digits that change marked, so a one-digit slip is obvious. */
function Diff({ typed, fix }: { typed: string; fix: string }) {
  const t = typed.replace(/^#/, "").toLowerCase()
  return (
    <span className="font-mono">
      #
      {Array.from(fix.replace(/^#/, "")).map((d, i) => (
        <span key={i} className={cn(d.toLowerCase() !== t[i] && "rounded-sm bg-amber-300/50 dark:bg-amber-400/25")}>
          {d}
        </span>
      ))}
    </span>
  )
}

/**
 * A colour field that stops near-miss brand colours from shipping. It names the closest token from
 * `palette` and offers a one-tap snap when a value is a hair off (#1e40ae vs the brand's #1e40af),
 * and catches pasted junk (`color: #1E40AF;`), the letter O for zero, a digit too many or few, alpha
 * hidden in 4- and 8-digit hex, and Android's #AARRGGBB order that CSS reads as a different colour.
 */
export function BrandColorInput({
  label = "Colour",
  value,
  defaultValue = "",
  onValueChange,
  onColorChange,
  palette = NO_PALETTE,
  messages,
  snapLabel = "Use",
  fixLabel = "Fix to",
  id,
  className,
  ref,
  ...props
}: BrandColorInputProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const text = value ?? inner
  const inputRef = React.useRef<HTMLInputElement>(null)
  const swatchRef = React.useRef<HTMLSpanElement>(null)
  const autoId = React.useId()
  const inputId = id ?? autoId
  const hintId = `${inputId}-hint`
  const m = { ...BRAND_COLOR_MESSAGES, ...messages }

  React.useImperativeHandle(ref, () => inputRef.current as HTMLInputElement)

  const reading = React.useMemo(() => readColor(text, palette), [text, palette])
  const issue = reading.issues[0]
  const lastHex = React.useRef<string | null | undefined>(undefined)
  React.useEffect(() => {
    if (lastHex.current !== reading.hex) onColorChange?.(reading.hex)
    lastHex.current = reading.hex
  }, [reading.hex, onColorChange])

  const update = (next: string) => {
    if (value === undefined) setInner(next)
    onValueChange?.(next)
  }

  const apply = (fix: string) => {
    update(fix)
    inputRef.current?.focus()
    if (!window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      swatchRef.current?.animate([{ transform: "scale(1.35)" }, { transform: "scale(1)" }], { duration: 300, easing: "ease-out" })
    }
  }

  const message = issue ? (issue.kind === "near" ? m.near(issue, reading) : m[issue.kind](issue)) : null

  return (
    <div data-slot="brand-color-input" className={cn("grid w-full max-w-sm gap-1.5", className)}>
      <label htmlFor={inputId} className="w-fit text-sm font-medium">
        {label}
      </label>
      <div className="relative">
        <span ref={swatchRef} className="absolute top-1.5 left-1.5 flex">
          <Swatch color={reading.hex} className="size-6" />
        </span>
        <input
          ref={inputRef}
          id={inputId}
          type="text"
          spellCheck={false}
          autoCapitalize="none"
          autoComplete="off"
          value={text}
          onChange={(event) => update(event.target.value)}
          aria-describedby={hintId}
          aria-invalid={issue?.kind === "unreadable" || (issue?.kind === "digits" && !issue.fix) || undefined}
          data-warning={issue && issue.kind !== "unreadable" ? "" : undefined}
          className={fieldClass}
          {...props}
        />
      </div>
      <div id={hintId} aria-live="polite" className="min-h-6 text-xs">
        {issue ? (
          <div className={cn("flex gap-1.5", issue.kind === "unreadable" ? "text-destructive" : "text-amber-700 dark:text-amber-400")}>
            <span className="flex h-6 shrink-0 items-center">
              <Pipette aria-hidden className="size-3.5" />
            </span>
            <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
              <span className="py-1">{message}</span>
              {issue.fix ? (
                <button
                  type="button"
                  onClick={() => apply(issue.fix!)}
                  aria-label={issue.token ? `${snapLabel} ${issue.token} ${issue.fix}` : `${fixLabel} ${issue.fix}`}
                  className={fixClass}
                >
                  {issue.kind === "near" && (
                    <span className="flex">
                      <Swatch color={reading.hex} className="h-3.5 w-2 rounded-r-none border-r-0" />
                      <Swatch color={issue.fix} className="h-3.5 w-2 rounded-l-none border-l-0" />
                    </span>
                  )}
                  {issue.token ? `${snapLabel} ${issue.token}` : fixLabel}
                  {issue.kind === "near" || issue.kind === "digits" || issue.kind === "lookalike" ? (
                    <Diff typed={issue.kind === "near" ? (reading.hex ?? text) : text} fix={issue.fix} />
                  ) : (
                    <span className="font-mono">{issue.fix}</span>
                  )}
                </button>
              ) : null}
            </span>
          </div>
        ) : reading.nearest && reading.rgba ? (
          <p className="flex gap-1.5 text-muted-foreground">
            <span className="flex h-6 shrink-0 items-center">
              {reading.nearest.exact ? (
                <Check aria-hidden className="size-3.5 text-emerald-600 dark:text-emerald-400" />
              ) : (
                <Swatch color={reading.nearest.hex} className="size-3.5" />
              )}
            </span>
            <span className="py-1">{reading.nearest.exact ? m.exact(reading) : m.nearest(reading)}</span>
          </p>
        ) : null}
      </div>
    </div>
  )
}

// Colour parsing and brand-palette matching behind BrandColorInput. Pure functions, safe on the server.

/** Red, green, blue (0–255) and alpha (0–1). */
export type RGBA = [r: number, g: number, b: number, a: number]

export type ColorIssueKind =
  | "unreadable"
  | "stray"
  | "lookalike"
  | "digits"
  | "argb"
  | "short-alpha"
  | "transparent"
  | "alpha-range"
  | "out-of-range"
  | "near"

export interface ColorIssue {
  kind: ColorIssueKind
  /** The text with the problem fixed, when there is one obvious fix. */
  fix?: string
  /** Palette token the fix snaps to. */
  token?: string
  /** Details for the message: what the browser will actually render, the digit count, the alpha. */
  detail?: string
}

export interface ColorReading {
  /** What the browser would render for the text as typed, or null if it can't read it. */
  rgba: RGBA | null
  /** Canonical CSS hex (#rrggbb or #rrggbbaa), or null. */
  hex: string | null
  /** Closest palette token by perceived difference, with ΔE OK (×2 a/b) and whether it is an exact match. */
  nearest: { token: string; hex: string; distance: number; exact: boolean } | null
  /** Problems in priority order; the first one is the one to show. */
  issues: ColorIssue[]
}

const byte = (n: number) => Math.max(0, Math.min(255, Math.round(n)))
const hex2 = (n: number) => byte(n).toString(16).padStart(2, "0")

/** #rrggbb, or #rrggbbaa when not opaque. */
export function toHex([r, g, b, a]: RGBA) {
  return `#${hex2(r)}${hex2(g)}${hex2(b)}${a < 1 ? hex2(a * 255) : ""}`
}

function fromHexDigits(digits: string): RGBA | null {
  if (!/^[0-9a-f]+$/i.test(digits)) return null
  const full = digits.length <= 4 ? digits.replace(/./g, "$&$&") : digits
  if (full.length !== 6 && full.length !== 8) return null
  const n = (i: number) => parseInt(full.slice(i, i + 2), 16)
  return [n(0), n(2), n(4), full.length === 8 ? n(6) / 255 : 1]
}

/** Removes what code and design tools wrap colours in: `color:`, quotes, `;`, `!important`, `0x`, spaces inside a hex. */
export function cleanColor(raw: string) {
  let text = raw.trim()
  text = text.replace(/^[a-z-]+\s*:\s*/i, "").replace(/\s*!important\s*$/i, "").replace(/[;,]+$/, "").trim()
  text = text.replace(/^(["'`])(.*)\1$/, "$2").trim()
  if (/^(0x|#+)?[\s0-9a-f]+$/i.test(text) && /[a-f]|^#|^0x|^\w{6}$/i.test(text)) text = "#" + text.replace(/^(0x|#+)/i, "").replace(/\s+/g, "")
  return text
}

function parseRgb(text: string): { rgba: RGBA; issue?: ColorIssue } | null {
  const m = text.match(/^rgba?\(\s*([^)]*)\)$/i) ?? text.match(/^(\d{1,3}\s*,\s*\d{1,3}\s*,\s*\d{1,3})$/)
  if (!m) return null
  const parts = m[1].split(/\s*[,/]\s*|\s+/).filter(Boolean)
  if (parts.length < 3 || parts.length > 4) return null
  const nums = parts.map((p) => (p.endsWith("%") ? parseFloat(p) / 100 : parseFloat(p)))
  if (nums.some(Number.isNaN)) return null
  const channels = parts.slice(0, 3).map((p, i) => (p.endsWith("%") ? nums[i] * 255 : nums[i]))
  let alpha = parts[3] ? nums[3] : 1
  let issue: ColorIssue | undefined
  if (channels.some((c) => c < 0 || c > 255)) issue = { kind: "out-of-range" }
  if (alpha > 1 && !parts[3].endsWith("%")) {
    // rgba(30, 64, 175, 255): alpha written as a byte. CSS clamps it to 1, which happens to look right until it's 128.
    issue = { kind: "alpha-range", detail: String(alpha) }
    alpha = alpha <= 255 ? alpha / 255 : 1
  }
  const rgba: RGBA = [byte(channels[0]), byte(channels[1]), byte(channels[2]), Math.max(0, Math.min(1, alpha))]
  if (issue) issue.fix = toHex(rgba)
  return { rgba, issue }
}

function linear(c: number) {
  const v = c / 255
  return v <= 0.04045 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4
}

/** sRGB to OKLab (Björn Ottosson, as used by CSS Color 4). */
export function toOklab([r, g, b]: RGBA): [number, number, number] {
  const [lr, lg, lb] = [linear(r), linear(g), linear(b)]
  const l = Math.cbrt(0.4122214708 * lr + 0.5363325363 * lg + 0.0514459929 * lb)
  const m = Math.cbrt(0.2119034982 * lr + 0.6806995451 * lg + 0.1073969566 * lb)
  const s = Math.cbrt(0.0883024619 * lr + 0.2817188376 * lg + 0.6299787005 * lb)
  return [
    0.2104542553 * l + 0.793617785 * m - 0.0040720468 * s,
    1.9779984951 * l - 2.428592205 * m + 0.4505937099 * s,
    0.0259040371 * l + 0.7827717662 * m - 0.808675766 * s,
  ]
}

/** Perceived difference: ΔE OK with a and b doubled, which tracks CIEDE2000 better (CSSWG issue 14207). */
export function colorDistance(x: RGBA, y: RGBA) {
  const [l1, a1, b1] = toOklab(x)
  const [l2, a2, b2] = toOklab(y)
  return Math.hypot(l1 - l2, 2 * (a1 - a2), 2 * (b1 - b2))
}

/** Below this two colours read as the same one; a typed value this close to a token is almost surely meant to be it. */
export const SAME_COLOR = 0.02
/** Below this a value is close enough to a token to offer snapping (eyedropper drift on a compressed screenshot). */
export const NEAR_COLOR = 0.06

export function nearestToken(rgba: RGBA, palette: Record<string, string>): ColorReading["nearest"] {
  let best: ColorReading["nearest"] = null
  for (const [token, value] of Object.entries(palette)) {
    const target = fromHexDigits(value.replace(/^#/, ""))
    if (!target) continue
    const distance = colorDistance(rgba, target)
    if (!best || distance < best.distance) best = { token, hex: toHex(target), distance, exact: toHex(target) === toHex([...rgba.slice(0, 3), 1] as RGBA) }
  }
  return best
}

/** Every hex string one digit away from `digits` (one inserted, deleted or changed). */
function oneDigitAway(digits: string) {
  const out = new Set<string>()
  const hexDigits = "0123456789abcdef"
  for (let i = 0; i <= digits.length; i++) {
    if (i < digits.length) out.add(digits.slice(0, i) + digits.slice(i + 1))
    for (const d of hexDigits) {
      out.add(digits.slice(0, i) + d + digits.slice(i))
      if (i < digits.length) out.add(digits.slice(0, i) + d + digits.slice(i + 1))
    }
  }
  return out
}

/** Finds a palette token that a malformed or slightly-off hex was meant to be. */
function tokenOneDigitAway(digits: string, palette: Record<string, string>) {
  const wanted = new Map(Object.entries(palette).map(([token, value]) => [value.replace(/^#/, "").toLowerCase(), token]))
  for (const candidate of oneDigitAway(digits.toLowerCase())) {
    const token = wanted.get(candidate)
    if (token) return { token, hex: "#" + candidate }
  }
  return null
}

/**
 * Reads a typed or pasted colour and lists what's surprising about it: stray characters, the letter O
 * for zero, a digit too many or few, Android #AARRGGBB order, alpha hidden in 4/8-digit hex, and a value
 * a hair off a brand token.
 */
export function readColor(raw: string, palette: Record<string, string> = {}): ColorReading {
  const issues: ColorIssue[] = []
  const text = cleanColor(raw)
  if (text !== raw.trim()) issues.push({ kind: "stray", fix: text })

  let rgba: RGBA | null = null
  const hexLike = text.match(/^#([0-9a-z]+)$/i)
  if (hexLike) {
    let digits = hexLike[1]
    if (/[oOlI]/.test(digits) && /^[0-9a-fA-FoOlI]+$/.test(digits)) {
      digits = digits.replace(/[oO]/g, "0").replace(/[lI]/g, "1")
      issues.push({ kind: "lookalike", fix: "#" + digits })
    }
    rgba = fromHexDigits(digits)
    if (!rgba && /^[0-9a-f]+$/i.test(digits)) {
      const meant = tokenOneDigitAway(digits, palette)
      issues.push({ kind: "digits", detail: String(digits.length), fix: meant?.hex, token: meant?.token })
    } else if (rgba && digits.length === 8) {
      // Android, Flutter and old IE write alpha first. If that reading is a brand colour, or the leading byte is FF
      // while CSS would make it translucent, the order is almost certainly swapped.
      const argb = fromHexDigits(digits.slice(2))!
      const argbToken = nearestToken(argb, palette)
      const leadingOpaque = /^ff/i.test(digits) && !/ff$/i.test(digits)
      if ((argbToken?.exact && !nearestToken(rgba, palette)?.exact) || leadingOpaque) {
        const alpha = parseInt(digits.slice(0, 2), 16) / 255
        issues.push({ kind: "argb", detail: `${toHex([rgba[0], rgba[1], rgba[2], 1])} at ${Math.round(rgba[3] * 100)}% opacity`, fix: toHex([argb[0], argb[1], argb[2], alpha]), token: argbToken?.exact ? argbToken.token : undefined })
      }
    }
    if (rgba && digits.length === 4 && rgba[3] < 1) issues.push({ kind: "short-alpha", detail: toHex(rgba), fix: "#" + digits.slice(0, 3) })
  } else {
    const rgb = parseRgb(text)
    if (rgb) {
      rgba = rgb.rgba
      if (rgb.issue) issues.push(rgb.issue)
    } else if (text) issues.push({ kind: "unreadable" })
  }
  if (rgba && rgba[3] === 0) issues.push({ kind: "transparent", fix: toHex([rgba[0], rgba[1], rgba[2], 1]) })

  const nearest = rgba ? nearestToken(rgba, palette) : null
  if (rgba && nearest && !nearest.exact && nearest.distance < NEAR_COLOR) {
    issues.push({ kind: "near", token: nearest.token, fix: rgba[3] < 1 ? toHex([...(fromHexDigits(nearest.hex.slice(1))!.slice(0, 3) as [number, number, number]), rgba[3]]) : nearest.hex })
  }
  return { rgba, hex: rgba ? toHex(rgba) : null, nearest, issues }
}
